#include <Wire.h>
#include <Servo.h>

const int MPU_ADDR = 0x68;
Servo gimbalServo;
int16_t ax, ay, az, gx, gy, gz;

void setup() {
  Wire.begin();
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x6B); // PWR_MGMT_1 register
  Wire.write(0);    // Wake up MPU-6050
  Wire.endTransmission(true);

  gimbalServo.attach(9);
  gimbalServo.write(90);
}

void loop() {
  Wire.beginTransmission(MPU_ADDR);
  Wire.write(0x3B); // Starting register for accelerometer
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDR, 6, true);

  ax = Wire.read() << 8 | Wire.read();
  ay = Wire.read() << 8 | Wire.read();
  az = Wire.read() << 8 | Wire.read();

  // Calculate tilt angle in degrees from gravity vector
  float angle = atan2(ay, az) * 180.0 / PI;
  int servoAngle = constrain(90 - (int)angle, 0, 180);
  gimbalServo.write(servoAngle);
  delay(20);
}
